USE minimall;

CREATE TABLE IF NOT EXISTS coupon (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, type INT NOT NULL, threshold DECIMAL(10,2) DEFAULT NULL, discount_value DECIMAL(10,2) NOT NULL, total_count INT DEFAULT 0, used_count INT DEFAULT 0, per_user_limit INT DEFAULT 1, start_time TIMESTAMP NULL DEFAULT NULL, end_time TIMESTAMP NULL DEFAULT NULL, status INT DEFAULT 1, seller_id BIGINT DEFAULT NULL, description VARCHAR(500) DEFAULT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_seller_id(seller_id), INDEX idx_status(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS user_coupon (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, coupon_id BIGINT NOT NULL, status INT DEFAULT 0, used_at TIMESTAMP NULL DEFAULT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_user_id(user_id), INDEX idx_coupon_id(coupon_id), INDEX idx_status(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS discount_activity (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, type INT NOT NULL, discount_rate DECIMAL(5,2) DEFAULT NULL, threshold DECIMAL(10,2) DEFAULT NULL, reduce_amount DECIMAL(10,2) DEFAULT NULL, start_time TIMESTAMP NULL DEFAULT NULL, end_time TIMESTAMP NULL DEFAULT NULL, status INT DEFAULT 1, seller_id BIGINT DEFAULT NULL, description VARCHAR(500) DEFAULT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_seller_id(seller_id), INDEX idx_status(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS discount_activity_product (id BIGINT AUTO_INCREMENT PRIMARY KEY, activity_id BIGINT NOT NULL, product_id BIGINT NOT NULL, discount_price DECIMAL(10,2) DEFAULT NULL, INDEX idx_activity_id(activity_id), INDEX idx_product_id(product_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS chat_session (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, seller_id BIGINT DEFAULT NULL, agent_id BIGINT DEFAULT NULL, product_id BIGINT DEFAULT NULL, order_id BIGINT DEFAULT NULL, status INT DEFAULT 1, session_type INT DEFAULT 0, source VARCHAR(50) DEFAULT NULL, auto_reply_enabled INT DEFAULT 1, user_unread INT DEFAULT 0, seller_unread INT DEFAULT 0, last_message_at TIMESTAMP NULL DEFAULT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, closed_at TIMESTAMP NULL DEFAULT NULL, close_reason VARCHAR(255) DEFAULT NULL, INDEX idx_user_id(user_id), INDEX idx_seller_id(seller_id), INDEX idx_status(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS chat_message (id BIGINT AUTO_INCREMENT PRIMARY KEY, session_id BIGINT NOT NULL, sender_id BIGINT NOT NULL, sender_type INT NOT NULL, receiver_id BIGINT DEFAULT NULL, content TEXT, image_url VARCHAR(500) DEFAULT NULL, message_type INT DEFAULT 0, file_name VARCHAR(255) DEFAULT NULL, file_size BIGINT DEFAULT NULL, related_order_id BIGINT DEFAULT NULL, related_product_id BIGINT DEFAULT NULL, is_read INT DEFAULT 0, read_at TIMESTAMP NULL DEFAULT NULL, status INT DEFAULT 1, delivered_at TIMESTAMP NULL DEFAULT NULL, is_auto_reply INT DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_session_id(session_id), INDEX idx_sender_id(sender_id), INDEX idx_created_at(created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS chat_notification (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, user_type INT DEFAULT 0, session_id BIGINT DEFAULT NULL, message_id BIGINT DEFAULT NULL, type VARCHAR(50) DEFAULT NULL, title VARCHAR(100) DEFAULT NULL, content VARCHAR(500) DEFAULT NULL, is_read INT DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_user_id(user_id), INDEX idx_is_read(is_read)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS after_sale_chat (id BIGINT AUTO_INCREMENT PRIMARY KEY, after_sale_id BIGINT NOT NULL, sender_id BIGINT NOT NULL, sender_type INT NOT NULL, content TEXT, message_type INT DEFAULT 0, is_read TINYINT DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, target_type VARCHAR(50) DEFAULT NULL, INDEX idx_after_sale_id(after_sale_id), INDEX idx_sender_id(sender_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS admin_intervention (id BIGINT AUTO_INCREMENT PRIMARY KEY, order_id BIGINT DEFAULT NULL, product_id BIGINT DEFAULT NULL, seller_id BIGINT DEFAULT NULL, user_id BIGINT DEFAULT NULL, session_id BIGINT DEFAULT NULL, aftersale_id BIGINT DEFAULT NULL, issue_type VARCHAR(50) DEFAULT NULL, title VARCHAR(100) DEFAULT NULL, description TEXT, evidence_images TEXT, status INT DEFAULT 0, admin_id BIGINT DEFAULT NULL, result VARCHAR(500) DEFAULT NULL, admin_remark VARCHAR(500) DEFAULT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, processed_at TIMESTAMP NULL DEFAULT NULL, INDEX idx_order_id(order_id), INDEX idx_seller_id(seller_id), INDEX idx_user_id(user_id), INDEX idx_status(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
